		CHECK(stdout_utf8_violations >= 0 AND stderr_utf8_violations >= 0),
		CHECK(stdout_redacted_segments >= 0 AND stderr_redacted_segments >= 0),
		CHECK(length(container_id_fingerprint) = 64
