CREATE TRIGGER trg_operator_steering_run_completion_guard
		BEFORE UPDATE OF status ON runs
		WHEN NEW.status = 'completed' AND OLD.status != 'completed'
			AND EXISTS (SELECT 1 FROM operator_steering_messages message
