-- traverse-board-clean-install-object-boundary --
CREATE TRIGGER trg_run_creation_operation_insert
		BEFORE INSERT ON run_creation_operations
		WHEN NOT EXISTS (
			SELECT 1
			FROM runs run
			JOIN missions mission ON mission.id = run.mission_id
			JOIN sessions session_record ON session_record.id = run.session_id
			JOIN workspaces workspace ON workspace.id = mission.workspace_id
			JOIN run_mode_snapshots mode ON mode.run_id = run.id AND mode.revision = 1
			JOIN run_execution_profile_snapshots execution_profile
				ON execution_profile.run_id = run.id AND execution_profile.revision = 1
			JOIN agent_nodes root ON root.run_id = run.id AND root.role = 'root'
			WHERE run.id = NEW.run_id AND run.mission_id = NEW.mission_id
				AND run.session_id = NEW.session_id
				AND mission.workspace_id = NEW.workspace_id
				AND session_record.workspace_id = NEW.workspace_id
				AND run.status = 'created' AND session_record.status = 'active'
				AND json_extract(run.config_json, '$.interactive') = 1
				AND (
					json_extract(run.config_json, '$.model_route') = mission.profile
					OR (
						typeof(json_extract(run.config_json, '$.model_route')) = 'text'
						AND json_extract(run.config_json, '$.model_route') =
							trim(json_extract(run.config_json, '$.model_route'))
						AND instr(json_extract(run.config_json, '$.model_route'), char(0)) = 0
						AND length(json_extract(run.config_json, '$.model_route')) BETWEEN 3 AND 513
						AND instr(json_extract(run.config_json, '$.model_route'), '/') BETWEEN 2 AND 257
						AND length(substr(json_extract(run.config_json, '$.model_route'),
							instr(json_extract(run.config_json, '$.model_route'), '/') + 1)) BETWEEN 1 AND 256
					)
				)
				AND (
					(json_type(run.config_json, '$.requested_budget') IS NULL
						AND json_extract(run.budget_json, '$.max_turns') = 100
						AND json_extract(run.budget_json, '$.max_tool_calls') = 100
						AND COALESCE(json_extract(run.budget_json, '$.max_tokens'), 0) = 0
						AND COALESCE(json_extract(run.budget_json, '$.max_cost_usd'), 0) = 0
						AND COALESCE(json_extract(run.budget_json, '$.timeout_seconds'), 0) = 0)
					OR (json_type(run.config_json, '$.requested_budget') = 'object'
						AND json_type(run.config_json, '$.requested_budget.max_turns') = 'integer'
						AND json_extract(run.config_json, '$.requested_budget.max_turns') BETWEEN 1 AND 10000
						AND json_type(run.config_json, '$.requested_budget.max_tool_calls') = 'integer'
						AND json_extract(run.config_json, '$.requested_budget.max_tool_calls') BETWEEN 1 AND 1000000
						AND COALESCE(json_type(run.config_json, '$.requested_budget.max_tokens'), 'integer') = 'integer'
						AND COALESCE(json_extract(run.config_json, '$.requested_budget.max_tokens'), 0) BETWEEN 0 AND 1000000000
						AND COALESCE(json_type(run.config_json, '$.requested_budget.timeout_seconds'), 'integer') = 'integer'
						AND COALESCE(json_extract(run.config_json, '$.requested_budget.timeout_seconds'), 0) BETWEEN 0 AND 604800
						AND COALESCE(json_type(run.config_json, '$.requested_budget.max_cost_usd'), 'real') IN ('real', 'integer')
						AND COALESCE(json_extract(run.config_json, '$.requested_budget.max_cost_usd'), 0) BETWEEN 0 AND 100000
						AND NOT EXISTS (SELECT 1 FROM json_each(run.config_json, '$.requested_budget') WHERE key NOT IN ('max_turns','max_tool_calls','max_tokens','max_cost_usd','timeout_seconds'))
						AND json_type(run.budget_json, '$.max_turns') = 'integer'
						AND json_extract(run.budget_json, '$.max_turns') BETWEEN 1 AND json_extract(run.config_json, '$.requested_budget.max_turns')
						AND json_type(run.budget_json, '$.max_tool_calls') = 'integer'
						AND json_extract(run.budget_json, '$.max_tool_calls') BETWEEN 1 AND json_extract(run.config_json, '$.requested_budget.max_tool_calls')
						AND COALESCE(json_extract(run.budget_json, '$.max_tokens'), 0) = COALESCE(json_extract(run.config_json, '$.requested_budget.max_tokens'), 0)
						AND COALESCE(json_extract(run.budget_json, '$.max_cost_usd'), 0) = COALESCE(json_extract(run.config_json, '$.requested_budget.max_cost_usd'), 0)
						AND COALESCE(json_extract(run.budget_json, '$.timeout_seconds'), 0) = COALESCE(json_extract(run.config_json, '$.requested_budget.timeout_seconds'), 0)
						AND (
							(json_type(run.config_json, '$.project_config') IS NULL
								AND COALESCE(json_extract(run.config_json, '$.project_config_fingerprint'), '') = ''
								AND json_extract(run.budget_json, '$.max_turns') = json_extract(run.config_json, '$.requested_budget.max_turns')
								AND json_extract(run.budget_json, '$.max_tool_calls') = json_extract(run.config_json, '$.requested_budget.max_tool_calls'))
							OR (json_type(run.config_json, '$.project_config') = 'object'
								AND json_extract(run.config_json, '$.project_config.protocol') = 'project_config.v1'
								AND length(json_extract(run.config_json, '$.project_config_fingerprint')) = 64
								AND json_extract(run.config_json, '$.project_config_fingerprint') NOT GLOB '*[^0-9a-f]*'
								AND json_extract(run.budget_json, '$.max_turns') = COALESCE(NULLIF(json_extract(run.config_json, '$.project_config.max_turns'), 0), json_extract(run.config_json, '$.requested_budget.max_turns'))
								AND json_extract(run.budget_json, '$.max_tool_calls') = COALESCE(NULLIF(json_extract(run.config_json, '$.project_config.max_tool_calls'), 0), json_extract(run.config_json, '$.requested_budget.max_tool_calls'))
								AND (COALESCE(json_extract(run.config_json, '$.project_config.read_only'), 0) = 0 OR mission.profile IN ('review', 'learn'))
								AND (COALESCE(json_array_length(run.config_json, '$.project_config.allowed_profiles'), 0) = 0 OR EXISTS (SELECT 1 FROM json_each(run.config_json, '$.project_config.allowed_profiles') WHERE value = mission.profile)))
							)
						)
					)
				AND json_extract(mission.scope_json, '$.workspace_id') = NEW.workspace_id
				AND (
					(json_extract(mission.scope_json, '$.network_mode') = 'disabled'
						AND COALESCE(json_array_length(mission.scope_json, '$.allowed_targets'), 0) = 0)
					OR (json_extract(mission.scope_json, '$.network_mode') = 'allowlist'
						AND json_array_length(mission.scope_json, '$.allowed_targets') BETWEEN 1 AND 256)
				)
				AND length(CAST(mission.goal AS BLOB)) BETWEEN 1 AND 4096
				AND session_record.route = json_extract(run.config_json, '$.model_route')
				AND session_record.title = mission.goal
				AND mission.created_at = NEW.created_at
				AND mission.updated_at = NEW.created_at
				AND session_record.created_at = NEW.created_at
				AND session_record.updated_at = NEW.created_at
				AND mode.mission_id = mission.id AND mode.profile = mission.profile
				AND mode.scope_json = mission.scope_json AND mode.requested_by = NEW.requested_by
				AND mode.created_at = NEW.created_at
				AND execution_profile.mission_id = mission.id
				AND execution_profile.profile = 'preview'
				AND execution_profile.backend = 'noop'
				AND execution_profile.approval_policy = 'none'
				AND execution_profile.filesystem_scope = 'none'
				AND execution_profile.network_scope = 'disabled'
				AND execution_profile.requested_by = NEW.requested_by
				AND execution_profile.process_enabled = 0
				AND execution_profile.execution_authorized = 0
				AND execution_profile.capability_grant = 0
				AND execution_profile.created_at = NEW.created_at
				AND root.parent_id IS NULL AND root.session_id = session_record.id
				AND root.profile = mission.profile AND root.status = 'ready' AND root.depth = 0
				AND root.child_limit = 0
				AND root.turn_limit = json_extract(run.budget_json, '$.max_turns')
				AND root.token_limit = COALESCE(json_extract(run.budget_json, '$.max_tokens'), 0)
				AND root.turns_used = 0 AND root.tokens_used = 0
				AND root.active_attempt_id = '' AND root.version = 1
				AND root.created_at = NEW.created_at AND root.updated_at = NEW.created_at
				AND run.created_at = NEW.created_at
				AND run.updated_at = NEW.created_at
				AND (SELECT COUNT(*) FROM run_events event
					WHERE event.run_id = run.id AND event.mission_id = mission.id
						AND event.type = 'run.created') = 1
				AND (SELECT COUNT(*) FROM run_events event
					WHERE event.run_id = run.id AND event.mission_id = mission.id
						AND event.type = 'session.attached') = 1
				AND (SELECT COUNT(*) FROM run_events event
					WHERE event.run_id = run.id AND event.mission_id = mission.id
						AND event.type = 'run.mode_selected') = 1
				AND (SELECT COUNT(*) FROM run_events event
					WHERE event.run_id = run.id AND event.mission_id = mission.id
						AND event.type = 'agent.registered') = 1
				AND (SELECT COUNT(*) FROM run_events event
					WHERE event.run_id = run.id AND event.mission_id = mission.id) = 4
		)
		BEGIN
			SELECT RAISE(ABORT, 'Run creation operation binding is invalid');
		END;
